fields.InputDefinition:
{
  "goal": "In the Version History app (application switcher dropdown next to the logo), click 'Dependency Graph' in the left nav. Then walk these interactions IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) depgraph-entity-select — confirm stat badges (entities / with dependents / relationships) and a scrollable entity list render, then select an entity from the list (use the filter box to find a common one like 'Users' if needed) and confirm the detail panel populates with 'Referenced By' and 'Depends On' sections listing related entities (one side may show a valid 'no relationships' state); (2) depgraph-search-filter — type into the 'Filter entities...' box and confirm the entity list narrows responsively; if schema filter chips are shown above the list, click one to filter entities to that schema and confirm the list narrows and the chip becomes active, then click it again (or clear the search) to restore the full list; (3) depgraph-relationship-nav — with an entity selected so its detail panel is loaded, click one of the related entities in the 'Referenced By' or 'Depends On' list and confirm the detail panel switches to that newly-clicked entity — its name becomes the detail title, its own Referenced By / Depends On relationships load, and it becomes the active/highlighted selection. Keep going until every interaction has been exercised. This works regardless of stored data. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "depgraph-entity-select",
      "instruction": "select an entity and view its relationships",
      "visualCriteria": [
        "The Dependency Graph shows entity stat badges and a list of entities; selecting an entity populates a detail panel with 'Referenced By' and 'Depends On' sections listing related entities or a valid 'no relationships' empty state"
      ]
    },
    {
      "name": "depgraph-search-filter",
      "instruction": "search entities and toggle a schema chip",
      "visualCriteria": [
        "Typing in the entity filter box responsively narrows the entity list, and clicking a schema filter chip (when present) narrows the list to that schema and toggles its active state, and clearing the search/schema restores the full entity list"
      ]
    },
    {
      "name": "depgraph-relationship-nav",
      "instruction": "navigate to a related entity from the detail panel",
      "visualCriteria": [
        "Clicking a related entity in the Referenced By / Depends On list switches the detail panel to that entity — its name becomes the detail title, its own relationship lists load, and it becomes the active/highlighted selection"
      ]
    }
  ]
}
